def apply(CONTENT, EN):
    newC, newEN = [], {}
    for slug, tfi, tru, fi, ru in CONTENT:
        o = OVR.get(slug, {}); en = list(EN[slug]); fi = list(fi); ru = list(ru); new = o.get("slug", slug)
        if "title" in o: tfi, tru, en[0] = o["title"]
        if "intro" in o: fi[0], ru[0], en[1] = o["intro"]
        if "items" in o: fi[1], ru[1], en[2] = (list(x) for x in o["items"])
        for i, (a, b, c) in o.get("items_replace", {}).items():
            fi[1], ru[1], en[2] = list(fi[1]), list(ru[1]), list(en[2]); fi[1][i], ru[1][i], en[2][i] = a, b, c
        newC.append((new, tfi, tru, tuple(fi), tuple(ru))); newEN[new] = tuple(en)
    return newC, newEN


